import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { formatDepth, relativeTime } from './format';
import { magColor } from './magnitude';
import type { Quake } from './types';

const ITEM = 74;

type EventListProps = {
  quakes: Quake[];
  selectedId: string | null;
  hoverId: string | null;
  now: number;
  onSelect: (id: string) => void;
  onHover: (id: string | null) => void;
  onReset: () => void;
  canReset: boolean;
};

export function EventList({ quakes, selectedId, hoverId, now, onSelect, onHover, onReset, canReset }: EventListProps) {
  const scrollerRef = useRef<HTMLDivElement>(null);
  const quakesRef = useRef(quakes);
  const [scrollTop, setScrollTop] = useState(0);
  const [height, setHeight] = useState(480);
  quakesRef.current = quakes;

  useLayoutEffect(() => {
    const element = scrollerRef.current;
    if (!element) return;
    const measure = () => setHeight(element.clientHeight || 480);
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const element = scrollerRef.current;
    if (!element || !selectedId) return;
    const index = quakesRef.current.findIndex((quake) => quake.id === selectedId);
    if (index < 0) return;
    const top = index * ITEM;
    const bottom = top + ITEM;
    if (top < element.scrollTop || bottom > element.scrollTop + element.clientHeight) {
      element.scrollTop = Math.max(0, top - element.clientHeight / 2 + ITEM / 2);
    }
  }, [selectedId]);

  const start = Math.max(0, Math.floor(scrollTop / ITEM) - 6);
  const count = Math.ceil(height / ITEM) + 12;
  const slice = quakes.slice(start, start + count);

  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp' || quakes.length === 0) return;
    event.preventDefault();
    const current = quakes.findIndex((quake) => quake.id === selectedId);
    const next =
      event.key === 'ArrowDown'
        ? current < 0
          ? 0
          : Math.min(quakes.length - 1, current + 1)
        : current < 0
          ? quakes.length - 1
          : Math.max(0, current - 1);
    onSelect(quakes[next].id);
  }

  if (quakes.length === 0) {
    return (
      <div className="empty">
        <p>{canReset ? 'No earthquakes match these filters.' : 'No earthquakes in this window.'}</p>
        {canReset ? (
          <button type="button" className="text-btn" onClick={onReset}>
            Clear filters
          </button>
        ) : null}
      </div>
    );
  }

  return (
    <div
      ref={scrollerRef}
      className="list"
      aria-label="Earthquakes"
      onScroll={(event) => {
        setScrollTop(event.currentTarget.scrollTop);
        onHover(null);
      }}
      onKeyDown={onKeyDown}
      onMouseLeave={() => onHover(null)}
    >
      <div className="list-space" style={{ height: quakes.length * ITEM }}>
        {slice.map((quake, index) => {
          const position = start + index;
          const pressed = quake.id === selectedId;
          return (
            <button
              key={quake.id}
              type="button"
              className={quake.id === hoverId ? 'row is-hover' : 'row'}
              style={{ top: position * ITEM, height: ITEM }}
              aria-pressed={pressed}
              onClick={() => onSelect(quake.id)}
              onMouseEnter={() => onHover(quake.id)}
            >
              <span className="row-mag" style={{ color: magColor(quake.mag) }}>
                {quake.mag.toFixed(1)}
              </span>
              <span className="row-copy">
                <span className="row-place">{quake.place}</span>
                <span className="row-meta">
                  {relativeTime(quake.time, now)} · {formatDepth(quake.depth)}
                </span>
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

import {
  depthZone,
  feltLabel,
  formatCoord,
  formatDepth,
  formatStamp,
  formatStampUtc,
  intensityLabel,
  magTypeLabel,
  significance,
  statusLabel,
} from './format';
import { magBand, magColor } from './magnitude';
import type { Quake } from './types';

type InspectorProps = {
  quake: Quake;
  onClose: () => void;
};

function Fact({ label, value, wide = false }: { label: string; value: string; wide?: boolean }) {
  return (
    <div className={wide ? 'span2' : undefined}>
      <dt>{label}</dt>
      <dd>{value}</dd>
    </div>
  );
}

export function Inspector({ quake, onClose }: InspectorProps) {
  const band = magBand(quake.mag);
  const zone = depthZone(quake.depth);
  const depthPct = Math.max(0, Math.min(100, (Math.max(0, quake.depth) / 700) * 100));
  const color = magColor(quake.mag);

  return (
    <aside className="inspector" aria-label="Earthquake detail">
      <div className="inspector-top">
        <p className="inspector-kicker">Selected event</p>
        <button type="button" className="text-btn" onClick={onClose}>
          Close
        </button>
      </div>
      <div className="inspector-hero">
        <p className="inspector-mag" style={{ color }}>
          {quake.mag.toFixed(1)}
        </p>
        <div>
          <p className="inspector-band" style={{ color }}>
            {band.label}
          </p>
          <p className="inspector-sub">
            {magTypeLabel(quake.magType)} · {statusLabel(quake.status)}
          </p>
        </div>
      </div>
      <p className="inspector-place">{quake.place}</p>
      <p className="inspector-time">{formatStamp(quake.time)}</p>
      <p className="inspector-time">{formatStampUtc(quake.time)}</p>
      {quake.type !== 'earthquake' ? <p className="kind">{quake.type}</p> : null}
      {quake.tsunami ? <p className="flag">USGS tsunami flag is set for this event.</p> : null}
      {quake.alert ? <p className={`pager pager-${quake.alert}`}>PAGER alert {quake.alert}</p> : null}
      <div className="depth-block">
        <div>
          <p className="depth-k">Depth</p>
          <p className="depth-v">{formatDepth(quake.depth)}</p>
          <p className="depth-note">
            {zone.label}. {zone.note}
          </p>
        </div>
        <div className="well" aria-hidden="true">
          <div className="well-track">
            <span className="well-mark" style={{ top: `calc(${depthPct}% - 1px)` }} />
          </div>
          <div className="well-labels">
            <span>surface</span>
            <span>700 km</span>
          </div>
        </div>
      </div>
      <dl className="facts">
        <Fact label="Coordinates" value={formatCoord(quake.lat, quake.lon)} wide />
        <Fact label="Significance" value={`${quake.sig.toLocaleString()} · ${significance(quake.sig)}`} />
        <Fact label="Felt reports" value={feltLabel(quake.felt)} />
        <Fact label="Community intensity" value={intensityLabel(quake.cdi)} wide />
        {quake.mmi !== null ? <Fact label="ShakeMap intensity" value={intensityLabel(quake.mmi)} /> : null}
        {quake.nst !== null ? <Fact label="Stations" value={quake.nst.toLocaleString()} /> : null}
        {quake.gap !== null ? <Fact label="Azimuthal gap" value={`${Math.round(quake.gap)}°`} /> : null}
        {quake.rms !== null ? <Fact label="RMS residual" value={`${quake.rms.toFixed(2)} s`} /> : null}
        {quake.dmin !== null ? <Fact label="Nearest station" value={`${quake.dmin.toFixed(2)}°`} /> : null}
      </dl>
      <a className="usgs" href={quake.url} target="_blank" rel="noopener noreferrer">
        USGS event page
      </a>
    </aside>
  );
}

