import { useCallback, useEffect, useMemo, useState } from 'react';
import { EventList } from './EventList';
import { depthNumber, formatStampUtc } from './format';
import { Inspector } from './Inspector';
import { inBand, MAG_STOPS, magColor, type MagStop } from './magnitude';
import { QuakeMap } from './QuakeMap';
import { regionById, REGIONS } from './regions';
import { Seismograph } from './Seismograph';
import type { DepthId, Quake, SortId, WindowId } from './types';
import { useQuakeFeed } from './useQuakeFeed';

const WINDOWS: ReadonlyArray<{ id: WindowId; label: string }> = [
  { id: 'hour', label: 'Past hour' },
  { id: 'day', label: 'Past day' },
  { id: 'week', label: 'Past week' },
  { id: 'month', label: 'Past month' },
];

const DEPTHS: ReadonlyArray<{ id: DepthId; label: string }> = [
  { id: 'any', label: 'Any depth' },
  { id: 'shallow', label: 'Shallow, under 70 km' },
  { id: 'intermediate', label: 'Intermediate, 70 to 300 km' },
  { id: 'deep', label: 'Deep, over 300 km' },
];

const SORTS: ReadonlyArray<{ id: SortId; label: string }> = [
  { id: 'newest', label: 'Newest' },
  { id: 'largest', label: 'Largest' },
  { id: 'shallowest', label: 'Shallowest' },
  { id: 'deepest', label: 'Deepest' },
];

function matchesDepth(depth: number, id: DepthId): boolean {
  if (id === 'shallow') return depth < 70;
  if (id === 'intermediate') return depth >= 70 && depth <= 300;
  if (id === 'deep') return depth > 300;
  return true;
}

function compareQuakes(sort: SortId) {
  return (a: Quake, b: Quake) => {
    if (sort === 'largest') return b.mag - a.mag || b.time - a.time;
    if (sort === 'shallowest') return a.depth - b.depth || b.mag - a.mag;
    if (sort === 'deepest') return b.depth - a.depth || b.mag - a.mag;
    return b.time - a.time;
  };
}

export function App() {
  const [windowId, setWindowId] = useState<WindowId>('week');
  const [minMag, setMinMag] = useState(0);
  const [bandId, setBandId] = useState<string | null>(null);
  const [depth, setDepth] = useState<DepthId>('any');
  const [sort, setSort] = useState<SortId>('newest');
  const [query, setQuery] = useState('');
  const [quakesOnly, setQuakesOnly] = useState(true);
  const [tsunamiOnly, setTsunamiOnly] = useState(false);
  const [regionId, setRegionId] = useState('world');
  const [viewToken, setViewToken] = useState(0);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [hoverId, setHoverId] = useState<string | null>(null);
  const [now, setNow] = useState(() => Date.now());
  const { status, quakes, meta, error, refresh } = useQuakeFeed(windowId);

  const region = regionById(regionId);
  const band = MAG_STOPS.find((stop) => stop.id === bandId) ?? null;
  const windowLabel = WINDOWS.find((item) => item.id === windowId)?.label ?? 'Past week';

  useEffect(() => {
    const timer = window.setInterval(() => {
      if (document.visibilityState === 'visible') setNow(Date.now());
    }, 30_000);
    return () => window.clearInterval(timer);
  }, []);

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setSelectedId(null);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, []);

  const scoped = useMemo(() => {
    const needle = query.trim().toLowerCase();
    return quakes.filter((quake) => {
      if (quakesOnly && quake.type.toLowerCase() !== 'earthquake') return false;
      if (tsunamiOnly && !quake.tsunami) return false;
      if (!region.contains(quake.lon, quake.lat)) return false;
      if (!matchesDepth(quake.depth, depth)) return false;
      if (needle && !quake.place.toLowerCase().includes(needle)) return false;
      return true;
    });
  }, [quakes, quakesOnly, tsunamiOnly, region, depth, query]);

  const visible = useMemo(() => {
    return scoped.filter((quake) => {
      if (quake.mag < minMag) return false;
      if (band && !inBand(quake.mag, band)) return false;
      return true;
    });
  }, [scoped, minMag, band]);

  const ordered = useMemo(() => [...visible].sort(compareQuakes(sort)), [visible, sort]);

  const summary = useMemo(() => {
    let strongest: Quake | null = null;
    let deepest: Quake | null = null;
    const counts: Record<string, number> = {};
    for (const stop of MAG_STOPS) counts[stop.id] = 0;
    for (const quake of scoped) {
      const stop = MAG_STOPS.find((item) => inBand(quake.mag, item));
      if (stop) counts[stop.id] += 1;
    }
    for (const quake of visible) {
      if (!strongest || quake.mag > strongest.mag) strongest = quake;
      if (!deepest || quake.depth > deepest.depth) deepest = quake;
    }
    return { strongest, deepest, counts };
  }, [scoped, visible]);

  const selected = useMemo(
    () => visible.find((quake) => quake.id === selectedId) ?? null,
    [visible, selectedId],
  );

  useEffect(() => {
    if (selectedId && !selected) setSelectedId(null);
  }, [selected, selectedId]);

  const selectQuake = useCallback((id: string) => {
    setSelectedId(id);
  }, []);

  const filtersDirty =
    minMag > 0 ||
    bandId !== null ||
    depth !== 'any' ||
    sort !== 'newest' ||
    query.trim() !== '' ||
    !quakesOnly ||
    tsunamiOnly ||
    regionId !== 'world';

  function resetFilters() {
    setMinMag(0);
    setBandId(null);
    setDepth('any');
    setSort('newest');
    setQuery('');
    setQuakesOnly(true);
    setTsunamiOnly(false);
    setRegionId('world');
    setViewToken((token) => token + 1);
  }

  function chooseBand(stop: MagStop) {
    if (bandId === stop.id) {
      setBandId(null);
      setMinMag(0);
      return;
    }
    setBandId(stop.id);
    setMinMag(stop.min);
  }

  function chooseRegion(id: string) {
    setRegionId(id);
    setSelectedId(null);
    setViewToken((token) => token + 1);
  }

  return (
    <div className="app" aria-busy={status === 'loading'}>
      <aside className="rail">
        <header className="mast">
          <div className="mast-row">
            <h1>Grok 4.7</h1>
            <button type="button" className="text-btn" onClick={refresh} disabled={status === 'loading'}>
              {status === 'loading' ? <span className="loading-word">Loading</span> : 'Refresh'}
            </button>
          </div>
          <p className="lede">
            {meta ? `${meta.title}. Generated ${formatStampUtc(meta.generated)}.` : 'Live earthquakes from USGS.'}
          </p>
          {error ? (
            <p className="error-line" role="alert">
              {error}{' '}
              <button type="button" className="text-btn" onClick={refresh}>
                Try again
              </button>
            </p>
          ) : null}
        </header>

        <div className="stats">
          <div className="stat">
            <span className="stat-k">On map</span>
            <span className="stat-v">{visible.length.toLocaleString()}</span>
          </div>
          <button
            type="button"
            className="stat"
            disabled={!summary.strongest}
            onClick={() => summary.strongest && selectQuake(summary.strongest.id)}
            aria-label={
              summary.strongest
                ? `Show strongest, magnitude ${summary.strongest.mag.toFixed(1)}`
                : 'Strongest'
            }
          >
            <span className="stat-k">Strongest</span>
            <span
              className="stat-v"
              style={{ color: summary.strongest ? magColor(summary.strongest.mag) : undefined }}
            >
              {summary.strongest ? summary.strongest.mag.toFixed(1) : '—'}
            </span>
          </button>
          <button
            type="button"
            className="stat"
            disabled={!summary.deepest}
            onClick={() => summary.deepest && selectQuake(summary.deepest.id)}
            aria-label={summary.deepest ? `Show deepest, ${depthNumber(summary.deepest.depth)} kilometers` : 'Deepest'}
          >
            <span className="stat-k">Deepest</span>
            <span className="stat-v">
              {summary.deepest ? depthNumber(summary.deepest.depth) : '—'}
              {summary.deepest ? <span className="stat-u"> km</span> : null}
            </span>
          </button>
        </div>

        <Seismograph quakes={visible} selectedId={selected?.id ?? null} onSelect={selectQuake} onHover={setHoverId} />

        <div className="controls">
          <div className="field">
            <span>Time window</span>
            <div className="segment" role="group" aria-label="Time window">
              {WINDOWS.map((item) => (
                <button
                  key={item.id}
                  type="button"
                  aria-pressed={item.id === windowId}
                  onClick={() => setWindowId(item.id)}
                >
                  {item.label.replace('Past ', '')}
                </button>
              ))}
            </div>
          </div>

          <label className="field">
            <span className="field-top">
              <span>Minimum magnitude</span>
              <span className="field-value">{minMag.toFixed(1)}</span>
            </span>
            <input
              type="range"
              min={0}
              max={8}
              step={0.1}
              value={Math.min(minMag, 8)}
              aria-valuetext={minMag.toFixed(1)}
              onChange={(event) => {
                setBandId(null);
                setMinMag(Math.round(Number(event.target.value) * 10) / 10);
              }}
            />
          </label>
          {band ? <p className="hint">Color filter is {band.label.toLowerCase()}, {band.hint}. Move the slider to clear it.</p> : null}

          <div className="pair">
            <label className="field">
              <span>Depth</span>
              <select value={depth} onChange={(event) => setDepth(event.target.value as DepthId)}>
                {DEPTHS.map((item) => (
                  <option key={item.id} value={item.id}>
                    {item.label}
                  </option>
                ))}
              </select>
            </label>
            <label className="field">
              <span>Sort</span>
              <select value={sort} onChange={(event) => setSort(event.target.value as SortId)}>
                {SORTS.map((item) => (
                  <option key={item.id} value={item.id}>
                    {item.label}
                  </option>
                ))}
              </select>
            </label>
          </div>

          <label className="field">
            <span>Map region</span>
            <select value={regionId} onChange={(event) => chooseRegion(event.target.value)}>
              {REGIONS.map((item) => (
                <option key={item.id} value={item.id}>
                  {item.label}
                </option>
              ))}
            </select>
          </label>

          <label className="field">
            <span>Place</span>
            <input
              type="search"
              value={query}
              placeholder="Search place"
              aria-label="Search place"
              onChange={(event) => setQuery(event.target.value)}
            />
          </label>

          <div className="checks">
            <label className="check">
              <input type="checkbox" checked={quakesOnly} onChange={(event) => setQuakesOnly(event.target.checked)} />
              Earthquakes only
            </label>
            <label className="check">
              <input
                type="checkbox"
                checked={tsunamiOnly}
                onChange={(event) => setTsunamiOnly(event.target.checked)}
              />
              Tsunami flag
            </label>
          </div>
          {filtersDirty ? (
            <button type="button" className="text-btn" onClick={resetFilters}>
              Clear filters
            </button>
          ) : null}
        </div>

        <p className="shown" aria-live="polite">
          {status === 'loading' && quakes.length === 0
            ? `Fetching the ${windowLabel.toLowerCase()} from USGS.`
            : `${ordered.length.toLocaleString()} shown${
                quakes.length !== ordered.length ? ` · ${quakes.length.toLocaleString()} in the feed` : ''
              }`}
        </p>

        {status === 'loading' && quakes.length === 0 ? (
          <p className="empty">Fetching the {windowLabel.toLowerCase()} from USGS.</p>
        ) : status === 'error' && quakes.length === 0 ? (
          <div className="empty">
            <p>{error}</p>
            <button type="button" className="text-btn" onClick={refresh}>
              Try again
            </button>
          </div>
        ) : (
          <EventList
            quakes={ordered}
            selectedId={selected?.id ?? null}
            hoverId={hoverId}
            now={now}
            onSelect={selectQuake}
            onHover={setHoverId}
            onReset={resetFilters}
            canReset={filtersDirty}
          />
        )}
      </aside>

      <main className={selected ? 'stage has-selection' : 'stage'}>
        <QuakeMap
          quakes={visible}
          selected={selected}
          hoverId={hoverId}
          onSelect={selectQuake}
          onHover={setHoverId}
          viewToken={viewToken}
          viewCenter={region.center}
          viewZoom={region.zoom}
        />
        <div className="legend">
          <p>
            Color is magnitude. Colder means smaller. White is 7 or above. A ring marks the last 3 hours.
            {minMag > 0 || band ? ' Totals skip the magnitude cut.' : ''}
          </p>
          <div className="swatches" role="group" aria-label="Magnitude colors">
            {MAG_STOPS.map((stop) => (
              <button
                key={stop.id}
                type="button"
                className="swatch"
                style={{ '--c': stop.color } as React.CSSProperties}
                aria-pressed={bandId === stop.id}
                aria-label={`${stop.label}, ${stop.hint}, ${summary.counts[stop.id] ?? 0} events`}
                onClick={() => chooseBand(stop)}
              >
                <i />
                <span>{stop.label}</span>
                <b>{(summary.counts[stop.id] ?? 0).toLocaleString()}</b>
              </button>
            ))}
          </div>
        </div>
        {selected ? <Inspector quake={selected} onClose={() => setSelectedId(null)} /> : null}
      </main>
    </div>
  );
}

:root {
  --space: #07141c;
  --panel: #0e2230;
  --ink: #07141c;
  --foam: #edf4f3;
  --mist: #9bb3b8;
  --brass: #e0c58a;
  --line: rgba(224, 197, 138, 0.32);
  color-scheme: dark;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  background: var(--space);
  color: var(--foam);
  font-family: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 13px;
  line-height: 1.45;
  font-variant-numeric: tabular-nums;
}

button,
input,
select { font: inherit; color: inherit; }

button { cursor: pointer; }

button:focus-visible,
select:focus-visible,
input:focus-visible,
a:focus-visible {
  outline: 2px solid #e6c15a;
  outline-offset: 2px;
}

::selection {
  background: var(--brass);
  color: #14202a;
}

.app {
  display: flex;
  height: 100dvh;
  min-height: 0;
  background: var(--space);
}

.rail {
  width: 392px;
  flex: none;
  display: flex;
  flex-direction: column;
  min-height: 0;
  background: var(--panel);
  border-right: 1px solid var(--line);
}

.mast {
  padding: 16px 14px 10px;
  border-bottom: 1px solid var(--line);
}

.mast-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

h1 {
  margin: 0;
  font-family: Syne, sans-serif;
  font-weight: 800;
  font-size: 28px;
  letter-spacing: -0.045em;
  line-height: 1;
}

.lede,
.error-line,
.hint,
.shown,
.trace-caption,
.empty p,
.depth-note,
.inspector-sub,
.inspector-time {
  color: var(--mist);
}

.lede,
.error-line {
  margin: 8px 0 0;
}

.error-line { color: #f0b4a8; }

.stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
  padding: 12px 14px 8px;
}

.stat {
  background: var(--ink);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 8px;
  text-align: left;
  min-width: 0;
}

button.stat:disabled {
  cursor: default;
  opacity: 0.72;
}

.stat-k {
  display: block;
  color: var(--mist);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.stat-v {
  display: block;
  margin-top: 4px;
  font-size: 20px;
  font-weight: 500;
  letter-spacing: -0.04em;
  white-space: nowrap;
}

.stat-u {
  color: var(--mist);
  font-size: 11px;
}

.trace-wrap {
  position: relative;
  margin: 4px 14px 8px;
  padding: 6px 6px 4px;
  border: 1px solid var(--line);
  border-radius: 4px;
  background:
    linear-gradient(180deg, rgba(224, 197, 138, 0.06), transparent 30%),
    repeating-linear-gradient(
      to bottom,
      transparent,
      transparent 16px,
      rgba(224, 197, 138, 0.14) 17px
    );
}

.trace {
  display: block;
  width: 100%;
  height: 78px;
}

.trace-grid { stroke: rgba(224, 197, 138, 0.28); stroke-width: 1; }

.trace-line {
  fill: none;
  stroke: var(--brass);
  stroke-width: 1.25;
  stroke-linejoin: round;
  stroke-linecap: round;
}

.trace-hit { cursor: pointer; }

.trace-empty {
  position: absolute;
  left: 8px;
  right: 8px;
  top: 18px;
  margin: 0;
  text-align: center;
  color: var(--mist);
}

.trace-caption {
  margin: 2px 2px 2px;
  font-size: 11px;
}

.controls {
  display: grid;
  gap: 8px;
  padding: 4px 14px 8px;
}

.field {
  display: grid;
  gap: 4px;
}

.field > span,
.field-top > span:first-child {
  color: var(--mist);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.field-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 8px;
}

.field-value {
  color: var(--brass);
  font-size: 13px;
  letter-spacing: 0;
  text-transform: none;
}

.segment {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  border: 1px solid var(--line);
  border-radius: 4px;
  overflow: hidden;
}

.segment button {
  background: transparent;
  color: var(--mist);
  border: 0;
  border-right: 1px solid rgba(224, 197, 138, 0.2);
  padding: 8px 2px;
}

.segment button:last-child { border-right: 0; }

.segment button[aria-pressed="true"] {
  background: var(--brass);
  color: #14202a;
  font-weight: 600;
}

input[type="range"] {
  width: 100%;
  accent-color: var(--brass);
}

input[type="search"],
select {
  width: 100%;
  background: var(--ink);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 7px 8px;
}

.pair {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.checks {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 14px;
}

.check {
  display: flex;
  align-items: center;
  gap: 6px;
}

.check input { accent-color: var(--brass); }

.hint { margin: 0; font-size: 11px; }

.text-btn,
.usgs {
  font: inherit;
  background: transparent;
  color: var(--brass);
  border: 1px solid rgba(224, 197, 138, 0.5);
  border-radius: 4px;
  padding: 6px 8px;
  text-decoration: none;
}

.text-btn:disabled {
  opacity: 0.55;
  cursor: progress;
}

.usgs {
  display: block;
  margin-top: 14px;
  text-align: center;
}

.shown {
  margin: 0;
  padding: 0 14px 6px;
  font-size: 11px;
}

.list {
  flex: 1;
  min-height: 0;
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(224, 197, 138, 0.45) transparent;
}

.list-space { position: relative; }

.row {
  position: absolute;
  left: 0;
  right: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 14px;
  background: transparent;
  border: 0;
  border-bottom: 1px solid rgba(224, 197, 138, 0.12);
  text-align: left;
}

.row.is-hover { background: #122c3b; }

.row[aria-pressed="true"] {
  background: #16384a;
  box-shadow: inset 3px 0 0 var(--brass);
}

.row-mag {
  width: 46px;
  flex: none;
  font-size: 18px;
  font-weight: 600;
}

.row-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.row-place {
  font-family: Literata, Georgia, serif;
  font-size: 14.5px;
  font-weight: 650;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.row-meta {
  color: var(--mist);
  font-size: 11px;
}

.empty {
  padding: 18px 14px;
  display: grid;
  gap: 10px;
  justify-items: start;
}

.empty p { margin: 0; }

.stage {
  position: relative;
  flex: 1;
  min-width: 0;
  min-height: 0;
  background: var(--space);
}

.map { position: absolute; inset: 0; }

.map-failed {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: grid;
  place-items: center;
  margin: 0;
  padding: 24px;
  text-align: center;
  background: rgba(7, 20, 28, 0.88);
}

.legend {
  position: absolute;
  z-index: 2;
  left: 12px;
  bottom: 42px;
  width: min(460px, calc(100% - 24px));
  padding: 8px;
  background: #0c1c27;
  border: 1px solid rgba(224, 197, 138, 0.4);
  border-radius: 6px;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.28);
}

.stage.has-selection .legend {
  width: min(460px, calc(100% - 380px));
}

.legend p {
  margin: 0 0 8px;
  color: var(--foam);
  font-size: 11px;
}

.swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}

.swatch {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 7px;
  background: #102838;
  border: 1px solid rgba(224, 197, 138, 0.22);
  border-radius: 99px;
  color: var(--foam);
}

.swatch i {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--c);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.45);
}

.swatch b { font-weight: 500; color: var(--mist); }

.swatch[aria-pressed="true"] {
  border-color: var(--brass);
  background: #17384a;
}

.inspector {
  position: absolute;
  z-index: 3;
  top: 96px;
  right: 12px;
  width: min(336px, calc(100% - 24px));
  max-height: calc(100% - 148px);
  overflow: auto;
  padding: 14px 14px 16px;
  background: #0c1c27;
  border: 1px solid rgba(224, 197, 138, 0.45);
  border-radius: 6px;
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.35);
  scrollbar-width: thin;
  scrollbar-color: rgba(224, 197, 138, 0.45) transparent;
}

.inspector-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.inspector-kicker {
  margin: 0;
  color: var(--mist);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.inspector-hero {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  margin-top: 8px;
}

.inspector-mag {
  margin: 0;
  font-size: 68px;
  line-height: 0.85;
  font-weight: 500;
  letter-spacing: -0.06em;
}

.inspector-band {
  margin: 0;
  font-family: Syne, sans-serif;
  font-size: 22px;
  font-weight: 700;
  letter-spacing: -0.03em;
}

.inspector-sub,
.inspector-time { margin: 4px 0 0; }

.inspector-place {
  margin: 12px 0 0;
  font-family: Literata, Georgia, serif;
  font-size: 22px;
  font-weight: 700;
  line-height: 1.25;
}

.kind,
.flag,
.pager {
  margin: 12px 0 0;
  padding: 8px 10px;
  border-radius: 4px;
}

.kind {
  border: 1px solid var(--line);
  text-transform: capitalize;
}

.flag {
  border: 1px solid var(--brass);
  color: var(--foam);
}

.pager-green { border: 1px solid #3cb89a; color: #9fe3cf; }
.pager-yellow { border: 1px solid #e6c15a; color: #e6c15a; }
.pager-orange { border: 1px solid #f08a3e; color: #f08a3e; }
.pager-red { border: 1px solid #e24b4b; color: #ffb4b4; }

.depth-block {
  display: grid;
  grid-template-columns: 1fr 86px;
  gap: 12px;
  margin-top: 14px;
  padding-top: 12px;
  border-top: 1px solid rgba(224, 197, 138, 0.22);
}

.depth-k {
  margin: 0;
  color: var(--mist);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.depth-v { margin: 4px 0 0; font-size: 16px; }

.depth-note { margin: 6px 0 0; font-size: 12px; }

.well {
  display: flex;
  gap: 6px;
  height: 88px;
}

.well-track {
  position: relative;
  width: 8px;
  height: 100%;
  background: #163244;
  border: 1px solid rgba(224, 197, 138, 0.45);
  border-radius: 99px;
}

.well-mark {
  position: absolute;
  left: -3px;
  width: 12px;
  height: 3px;
  background: var(--brass);
}

.well-labels {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  color: var(--mist);
  font-size: 10px;
}

.facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 14px;
  margin: 14px 0 0;
}

.facts dt {
  margin: 0;
  color: var(--mist);
  font-size: 10px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.facts dd { margin: 2px 0 0; }

.span2 { grid-column: 1 / -1; }

.maplibregl-ctrl-group {
  background: #f3efe6;
  border-radius: 4px;
  overflow: hidden;
}

.maplibregl-ctrl-attrib {
  background: rgba(7, 20, 28, 0.82);
  color: var(--mist);
  font-family: "IBM Plex Mono", ui-monospace, monospace;
  font-size: 10px;
}

.maplibregl-ctrl-attrib a { color: var(--brass); }

.maplibregl-ctrl-scale {
  background: rgba(7, 20, 28, 0.82);
  border-color: var(--brass);
  color: var(--foam);
  font-family: "IBM Plex Mono", ui-monospace, monospace;
}

@keyframes pulse {
  50% { opacity: 0.45; }
}

.loading-word { animation: pulse 1.1s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
  .loading-word { animation: none; }
}

@media (max-width: 900px) {
  .app { flex-direction: column; }

  .stage {
    flex: none;
    height: 56dvh;
    order: -1;
  }

  .rail {
    width: 100%;
    flex: 1;
    border-right: 0;
    border-top: 1px solid var(--line);
  }

  .inspector {
    top: auto;
    right: 8px;
    left: 8px;
    bottom: 8px;
    width: auto;
    max-height: 48%;
  }

  .legend,
  .stage.has-selection .legend {
    top: 8px;
    bottom: auto;
    left: 8px;
    width: min(460px, calc(100% - 68px));
  }

  .inspector-mag { font-size: 52px; }
}

