:root {
  --space: #07141c;
  --panel: #0e2230;
  --ink: #07141c;
  --foam: #edf4f3;
  --mist: #9bb3b8;
  --brass: #e0c58a;
  --line: rgba(224, 197, 138, 0.32);
  color-scheme: dark;
  font-synthesis: none;
