    setMinMag(0);
    setBandId(null);
    setDepth('any');
    setSort('newest');
    setQuery('');
    setQuakesOnly(true);
    setTsunamiOnly(false);
    setRegionId('world');
    setViewToken((token) => token + 1);
  }

