dev-browser --browser earthquake <<'EOF'
const page = await browser.getPage("quake");
const box = await page.locator(".maplibregl-canvas").boundingBox();
const tries = [];
const points = [
  [0.42, 0.62],
  [0.48, 0.66],
  [0.55, 0.58],
  [0.62, 0.64],
  [0.38, 0.7],
  [0.5, 0.72],
];
for (const [px, py] of points) {
  const x = box.x + box.width * px;
  const y = box.y + box.height * py;
  await page.mouse.click(x, y);
  await page.waitForTimeout(350);
  const open = await page.locator(".inspector").count();
  tries.push({ px, py, open });
  if (open) {
    tries[tries.length - 1].place = await page.locator(".inspector-place").innerText();
    tries[tries.length - 1].mag = await page.locator(".inspector-mag").innerText();
    break;
  }
}
const shot = await saveScreenshot(await page.screenshot(), "quake-map-click.png");
console.log(JSON.stringify({ box, tries, shot }));
